/**
 * The append-only audit log.
 *
 * Every routing decision and every observed outcome can be recorded as an immutable entry. Sealing the
 * log folds its entries into a SHA-256 hash chain whose root is a tamper-evident fingerprint: changing,
 * reordering, inserting, or dropping any entry changes the root, so a later verification against a
 * stored seal proves the log is intact. The hash uses the Web Crypto API (`crypto.subtle`), never a
 * Node built-in, so the audit trail works in Node, edge runtimes, and the browser.
 *
 * @packageDocumentation
 */

import { canonicalize } from '../canonical.js';
import { BayesRouteError } from '../errors.js';
import { cyrb53 } from '../hash.js';
import type { AuditEntry, AuditEventType, AuditLog, AuditSeal, VerifyResult } from '../types.js';

export type { AuditEntry, AuditEventType, AuditLog, AuditSeal, VerifyResult } from '../types.js';

/** Create an empty audit log with a stable, content-derived id. */
export function createAuditLog(seed = 'bayesroute'): AuditLog {
  return { id: `route-${cyrb53(seed)}`, entries: [] };
}

/** Append one entry and return a new log. Sequence numbers are one-based and contiguous. */
export function appendEntry(
  log: AuditLog,
  type: AuditEventType,
  summary: string,
  at: number,
  data?: unknown,
): AuditLog {
  const seq = log.entries.length + 1;
  const entry: AuditEntry =
    data === undefined ? { seq, at, type, summary } : { seq, at, type, summary, data };
  return { id: log.id, entries: [...log.entries, entry] };
}

async function sha256Hex(input: string): Promise<string> {
  const bytes = new TextEncoder().encode(input);
  const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function chainRoot(log: AuditLog): Promise<string> {
  let running = log.id;
  for (const entry of log.entries) {
    running = await sha256Hex(`${running}|${canonicalize(entry)}`);
  }
  return running;
}

/** Seal the log: compute its SHA-256 hash-chain root and entry count. */
export async function sealAuditLog(log: AuditLog): Promise<AuditSeal> {
  return { algorithm: 'sha-256', root: await chainRoot(log), count: log.entries.length };
}

/**
 * Verify a log against a previously stored seal. A count mismatch is reported with the divergence
 * point; a content change is detected as an invalid root. A matching root and count is valid.
 */
export async function verifyAuditLog(log: AuditLog, seal: AuditSeal): Promise<VerifyResult> {
  if (seal.algorithm !== 'sha-256') {
    throw new BayesRouteError('ERR_INVALID_AUDIT', `unsupported seal algorithm ${seal.algorithm}`);
  }
  if (seal.count !== log.entries.length) {
    return { valid: false, brokenAt: Math.min(seal.count, log.entries.length) };
  }
  const root = await chainRoot(log);
  return root === seal.root ? { valid: true } : { valid: false };
}
